import numpy as np

def solve(anchor,wrist,u,l):
 ax,ay=anchor;wx,wy=wrist;dx,dy=wx-ax,wy-ay;d=np.hypot(dx,dy); d=min(d,u+l-1e-3)
 along=(u*u-l*l+d*d)/(2*d); h=np.sqrt(max(0,u*u-along*along)); ux,uy=dx/d,dy/d;mx,my=ax+along*ux,ay+along*uy
 return (mx-h*uy,my+h*ux),(mx+h*uy,my-h*ux)
